-- Phase 1: accounts, profile, resumes.
-- UUIDs are generated by the app (keeps this file portable to the H2 test database).

CREATE TABLE users (
    id            UUID PRIMARY KEY,
    email         VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(100) NOT NULL,
    full_name     VARCHAR(120) NOT NULL,
    created_at    TIMESTAMP WITH TIME ZONE NOT NULL
);

-- One profile per user. This is the "verified data" the agent may use later:
-- it never states anything about the user that is not in these tables.
CREATE TABLE profiles (
    user_id             UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    headline            VARCHAR(200),
    phone               VARCHAR(30),
    location            VARCHAR(120),
    current_title       VARCHAR(120),
    years_experience    NUMERIC(4,1),
    expected_salary     BIGINT,
    salary_currency     VARCHAR(3),
    notice_period_days  INTEGER,
    work_authorization  VARCHAR(200),
    willing_to_relocate BOOLEAN NOT NULL DEFAULT FALSE,
    linkedin_url        VARCHAR(300),
    github_url          VARCHAR(300),
    portfolio_url       VARCHAR(300),
    summary             TEXT,
    updated_at          TIMESTAMP WITH TIME ZONE NOT NULL
);

CREATE TABLE profile_skills (
    user_id  UUID NOT NULL REFERENCES profiles(user_id) ON DELETE CASCADE,
    position INTEGER NOT NULL,
    skill    VARCHAR(80) NOT NULL,
    PRIMARY KEY (user_id, position)
);

CREATE TABLE profile_desired_roles (
    user_id  UUID NOT NULL REFERENCES profiles(user_id) ON DELETE CASCADE,
    position INTEGER NOT NULL,
    role     VARCHAR(120) NOT NULL,
    PRIMARY KEY (user_id, position)
);

CREATE TABLE profile_desired_locations (
    user_id  UUID NOT NULL REFERENCES profiles(user_id) ON DELETE CASCADE,
    position INTEGER NOT NULL,
    location VARCHAR(120) NOT NULL,
    PRIMARY KEY (user_id, position)
);

CREATE TABLE profile_experiences (
    user_id     UUID NOT NULL REFERENCES profiles(user_id) ON DELETE CASCADE,
    position    INTEGER NOT NULL,
    company     VARCHAR(160) NOT NULL,
    title       VARCHAR(160) NOT NULL,
    location    VARCHAR(120),
    start_date  DATE NOT NULL,
    end_date    DATE,                -- NULL = current job
    description TEXT,
    PRIMARY KEY (user_id, position)
);

CREATE TABLE profile_educations (
    user_id     UUID NOT NULL REFERENCES profiles(user_id) ON DELETE CASCADE,
    position    INTEGER NOT NULL,
    institution VARCHAR(200) NOT NULL,
    degree      VARCHAR(120) NOT NULL,
    field       VARCHAR(120),
    start_year  INTEGER,
    end_year    INTEGER,
    grade       VARCHAR(40),
    PRIMARY KEY (user_id, position)
);

CREATE TABLE resumes (
    id                UUID PRIMARY KEY,
    user_id           UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    label             VARCHAR(120) NOT NULL,
    original_filename VARCHAR(255) NOT NULL,
    content_type      VARCHAR(100) NOT NULL,
    size_bytes        BIGINT NOT NULL,
    sha256            VARCHAR(64) NOT NULL,
    storage_key       VARCHAR(100) NOT NULL UNIQUE,
    extracted_text    TEXT,
    is_primary        BOOLEAN NOT NULL DEFAULT FALSE,
    created_at        TIMESTAMP WITH TIME ZONE NOT NULL
);
CREATE INDEX idx_resumes_user ON resumes(user_id);
